<?php use VoiceShop\Http\Csrf; use VoiceShop\Domain\StatusFlow; ?>
<p><a href="index.php">← Orders</a></p><div class="heading"><div><p class="eyebrow"><?= $e($config['shop_name']) ?></p><h1>Order #<?= (int)$order['id'] ?></h1></div><span class="badge <?= $e($order['status']) ?>"><?= $e(StatusFlow::label($order['status'])) ?></span></div>
<p><?= $order['is_demo'] ? 'Demo data · ' : '' ?><?= $e($order['language']) ?> · Call <code><?= $e($order['call_id']) ?></code></p><p class="muted">Created <?= $e($order['created_at']) ?> · Updated <?= $e($order['updated_at']) ?></p>
<?php if ($order['missing']): ?><div class="error"><strong>Missing</strong><ul><?php foreach ($order['missing'] as $field): ?><li><?= $e($field) ?></li><?php endforeach ?></ul></div><?php elseif ($order['status'] === 'NEEDS_DETAILS'): ?><div class="notice">Details are complete. You can now move this order to Awaiting Merchant Approval using the button below.</div><?php endif ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?= $e(Csrf::token()) ?>"><input type="hidden" name="action" value="save"><h2>Customer &amp; delivery</h2><div class="fields">
<label>Name<input name="customer[name]" maxlength="255" value="<?= $e($order['customer_name']) ?>" class="<?= in_array('customer_name', $order['missing'], true) ? 'missing' : '' ?>"></label><label>Phone<input name="customer[phone]" type="tel" maxlength="50" value="<?= $e($order['customer_phone']) ?>" class="<?= in_array('phone', $order['missing'], true) ? 'missing' : '' ?>"></label>
<?php foreach ($config['required_fields']['address']['parts'] as $part): ?><label><?= $e(ucwords(str_replace('_',' ', $part))) ?><input name="customer[address][<?= $e($part) ?>]" maxlength="255" value="<?= $e($order['address'][$part] ?? '') ?>" class="<?= in_array('address.' . $part, $order['missing'], true) ? 'missing' : '' ?>"></label><?php endforeach ?>
<?php foreach (['delivery' => 'delivery_choice','payment' => 'payment_choice'] as $key => $field): ?><label><?= $e(ucfirst($key)) ?><select name="<?= $e($field) ?>"><option value="">Not specified</option><?php foreach ($config[$key]['options'] as $option): ?><option value="<?= $e($option) ?>" <?= $order[$field] === $option ? 'selected' : '' ?>><?= $e(str_replace('_',' ', $option)) ?></option><?php endforeach ?></select></label><?php endforeach ?><label>Requested time<input name="requested_time" maxlength="255" value="<?= $e($order['requested_time']) ?>"></label></div>
<h2>Items · Owner prices</h2><?php foreach ($items as $i): ?><section class="item"><h3><?= $e($i['display_name']) ?> <?= $i['is_unknown_item'] ? '(unknown item)' : '' ?></h3><p><code><?= $e($i['sku']) ?></code> · <?= $e($i['raw_text']) ?></p><div class="fields"><label>Quantity<input type="number" min="0.001" max="999999999" step="0.001" required name="items[<?= (int)$i['id'] ?>][qty]" value="<?= $e($i['qty']) ?>"></label><label>Unit<select name="items[<?= (int)$i['id'] ?>][unit]"><?php foreach ($i['allowed_units'] as $unit): ?><option <?= $i['unit'] === $unit ? 'selected' : '' ?> value="<?= $e($unit) ?>"><?= $e($unit) ?></option><?php endforeach ?></select></label></div><p>Config price: <?= $i['price'] === null ? 'Not priced' : '₹' . $e(number_format($i['price'], 2)) ?> · Line total: <?= $i['line_total'] === null ? 'Not priced' : '₹' . $e(number_format($i['line_total'], 2)) ?></p><?php foreach ($i['options'] as $key => $value): ?><span class="chip"><?= $e($key) ?>: <?= $e($value) ?></span><?php endforeach ?></section><?php endforeach ?>
<p><strong>Known-item total: ₹<?= $e(number_format($total, 2)) ?></strong> <?= $unpriced ? '(unknown items excluded)' : '' ?></p><p class="muted">Prototype estimate: config price × quantity in the selected unit. See README for alternate-unit assumptions.</p>
<?php foreach ($order['extra_missing'] as $field): ?><label><input type="checkbox" name="resolve_missing[]" value="<?= $e($field) ?>"> I have resolved extraction note: <?= $e($field) ?></label><?php endforeach ?><button>Save details</button></form>
<section class="panel"><h2>Next step</h2><div class="row"><?php foreach ($next as $status): ?><form method="post"><input type="hidden" name="csrf" value="<?= $e(Csrf::token()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="status" value="<?= $e($status) ?>"><button <?= ($status === 'CONFIRMED' && !$owner) || ($status === 'AWAITING_MERCHANT_APPROVAL' && $order['missing']) ? 'disabled' : '' ?>><?= $e($status === 'CONFIRMED' ? 'Approve → Confirmed' : StatusFlow::label($status)) ?></button></form><?php endforeach ?></div><?php if (!$owner && in_array('CONFIRMED', $next, true)): ?><p>Enable Owner mode with your PIN to approve this order.</p><?php endif ?><?php if (!$next): ?><p>No further transitions.</p><?php endif ?></section>
<section class="panel"><h2>Flags</h2><?php if (!$order['flags']): ?><p>None</p><?php endif ?><?php foreach ($order['flags'] as $flag): ?><span class="chip"><?= $e($flag) ?></span><?php endforeach ?></section>
<section class="panel"><h2>Message to customer would be:</h2><p>Preview only — nothing is sent.</p><?php foreach ($previews as $key => $p): ?><h3><?= $e(str_replace('_',' ', $key)) ?></h3><p><?= $e($p['value']) ?> <?php if ($p['fallback']): ?><span class="chip">fallback · <?= $e($p['language']) ?></span><?php endif ?></p><?php endforeach ?></section>
<section class="panel"><h2>Status history</h2><?php foreach ($history as $log): ?><p><strong><?= $e(StatusFlow::label($log['from_status'])) ?> → <?= $e(StatusFlow::label($log['to_status'])) ?></strong><br><?= $e($log['changed_at']) ?> · <?= $e($log['changed_by']) ?> <?= $e($log['note']) ?></p><?php endforeach ?></section>
